H2="Subject: a Chilean boy, 6 years old, child proportions, of Spanish descent, light skin with warm golden undertone, clearly Latin American and NOT Nordic. Brown eyes, short medium-brown hair slightly messy with a cowlick, gap in front baby teeth. Playful, cheeky natural child."
run(){ py scripts/magnific.py seedream "$2 $BASE" --aspecto feed --out raw/hilton/dt/familia/r1/$1.png > raw/hilton/dt/familia/r1/$1.log 2>&1; }
run mama-B "$M1" & run mama-C "$M2" & run papa-A "$P1" & run papa-B "$P2" & run nina-A "$N1" & run nina-B "$N2" & run nino-A "$H1" & run nino-B "$H2" & wait
